 '<section class="card elevation-card"><div class="card-heading"><div><p class="eyebrow">BANPROFIL</p><h2>'+esc(a.race.race_family==='ultra60'||a.race.race_family==='duo60'?'Från kust till slott':'Ekopark, skog och Österlen')+'</h2><p class="panel-copy">Höjdprofil från den lokalt tillgängliga ruttens referensdata. Saknad eller otillåten rutt ersätts inte med en annan upplaga.</p></div><span class="badge" id="overview-elevation-source">Ruttdata efter behov</span></div><div id="overview-elevation" class="elevation-chart">'+empty('Laddar höjdprofil när ruttunderlaget finns…')+'</div></section>';
