export function progression(f){if(!f.length)return empty('Inga fullföljare i urvalet.');return [10,25,50,75,90].map(p=>'<div class="progress-row"><span>'+p+' %'+(p===50?' · median':'')+'</span><div class="progress-track"><span style="width:'+p+'%"></span></div><strong>'+time(percentileValue(f.map(r=>r.finish_seconds),p))+'</strong></div>').join('')+'<p class="chart-caption">Median kräver n ≥ 5, 25/75 % n ≥ 10 och 10/90 % n ≥ 20. Ingen prognos.</p>';}
