 const doneF=known.filter(r=>r.sex==='F'&&finished(r)),doneM=known.filter(r=>r.sex==='M'&&finished(r)),medF=doneF.length>=5?quantile(doneF.map(r=>r.finish_seconds),.5):null,medM=doneM.length>=5?quantile(doneM.map(r=>r.finish_seconds),.5):null,startersF=known.filter(r=>r.sex==='F'&&['FINISHED','DNF','DSQ'].includes(r.status)),startersM=known.filter(r=>r.sex==='M'&&['FINISHED','DNF','DSQ'].includes(r.status)),insights=[];
