 const makeGroup=(id,label,all,index)=>{const starters=all.filter(r=>['FINISHED','DNF','DSQ'].includes(r.status)),finishers=all.filter(finished);return {id,label,index,all,starters,finishers,stats:a.race.capabilities.segment_analysis?a.segmentStats(all):[]};};
 let available,team=a.race.participant.entity==='team';
 if(team){
  const names=[...new Set(rows.map(r=>String(r.class_name||'').trim()).filter(Boolean))].sort((x,y)=>x.localeCompare(y,'sv',{numeric:true}));
  available=names.map((name,index)=>makeGroup('class-'+index,name,rows.filter(r=>r.class_name===name),index)).filter(g=>g.all.length>=5);
 }else{
  available=AGE_GROUPS.map((g,index)=>makeGroup(g.id,g.label,rows.filter(r=>finite(r.age)&&Number(r.age)>=g.from&&Number(r.age)<g.to),index)).filter(g=>g.all.length>=5);
 }
 if(!available.length)return empty(team?'För få lag i publicerade klasser för klassanalys.':'För få resultat med exakt publicerad ålder för Gotaledens åldersgrupper.');
 const validIds=new Set(available.map(g=>g.id)),requested=(state.ageGroups||[]).filter(id=>validIds.has(id));if(!requested.length)requested.push(...available.slice(0,5).map(g=>g.id));state.ageGroups=requested.slice(0,5);
 const selected=available.filter(g=>state.ageGroups.includes(g.id)),labels=a.boundary.slice(1).map(cp=>cp.name),colorOf=g=>colors[g.index%colors.length],stat=state.ageHeatStat==='fastest10'?'fastest10':'median';
 const paceChart=a.race.capabilities.segment_analysis?lines(selected.map(g=>({id:g.id,name:g.label,color:colorOf(g),values:g.stats.map(x=>x.median)})),labels,{format:v=>pace(v,state.unit)}):empty('Delsträckor saknas.');
 const summaryHtml='<div class="age-summary-list">'+selected.map(g=>'<article style="--age-color:'+colorOf(g)+'"><span>'+esc(g.label)+'</span><strong>'+g.all.length+'</strong><small>'+(g.starters.length?Math.round(100*g.finishers.length/g.starters.length):0)+' % fullföljde · median '+time(g.finishers.length>=5?quantile(g.finishers.map(r=>r.finish_seconds),.5):null)+'</small></article>').join('')+'</div>';
 const summarize=(g,i)=>{const values=g.all.map(r=>a.segment(r,i)?.pace).filter(v=>finite(v)&&v>0).sort((x,y)=>x-y);if(!values.length)return {value:null,count:0,total:0};if(stat==='fastest10'){const count=Math.max(1,Math.ceil(values.length*.1)),pick=values.slice(0,count);return {value:pick.reduce((s,v)=>s+v,0)/count,count,total:values.length};}return {value:values.length>=5?quantile(values,.5):null,count:values.length,total:values.length};};
 const heat=selected.map(g=>({g,cells:labels.map((_,i)=>summarize(g,i))})),allValues=heat.flatMap(row=>row.cells.map(x=>x.value).filter(finite)),min=allValues.length?Math.min(...allValues):0,max=allValues.length?Math.max(...allValues):1;
 const cell=x=>{if(!finite(x.value))return '<span class="heat-empty">–</span>';const ratio=(x.value-min)/(max-min||1),light=92-ratio*42,display=pace(x.value,state.unit);return '<span style="background:hsl('+(165-ratio*120)+' 48% '+light+'%)" title="'+esc(display+' · '+x.count+' av '+x.total+' giltiga')+'">'+esc(display.replace(' min/km','').replace(' km/h',''))+'</span>';};
 const heatmap=a.race.capabilities.segment_analysis?'<div class="heatmap-grid" style="--heat-cols:'+(labels.length+1)+'"><b>'+(team?'Klass':'Grupp')+'</b>'+labels.map(label=>'<b>'+esc(label)+'</b>').join('')+heat.map(row=>'<strong>'+esc(row.g.label)+'</strong>'+row.cells.map(cell).join('')).join('')+'</div>':empty('Delsträckor saknas.');
 const controls='<div class="age-group-controls">'+available.map(g=>'<button type="button" data-age-group="'+esc(g.id)+'" aria-pressed="'+state.ageGroups.includes(g.id)+'" style="--age-color:'+colorOf(g)+'">'+esc(g.label)+' <small>'+g.all.length+'</small></button>').join('')+'</div>';
 const title=team?'Klassanalys':'Ålderslabbet',eyebrow=team?'OFFICIELLA KLASSER':'KLASS & ÅLDER',copy=team?'Jämförelsen använder endast publicerade lagklasser. Ingen medlem kopplas till etapp eller individuell ålder.':'Analytiska åldersgrupper – inte officiella tävlingsklasser. Grupperna visas alltid i åldersordning.';
 const retention=team&&a.race.capabilities.segment_analysis?'<section class="card"><div class="card-heading"><div><p class="eyebrow">KLASSVIS PACING</p><h3>Fartretention per klass</h3></div><span class="badge">100 = respektive klass egen hel-loppsmedianfart</span></div>'+lines(selected.map(g=>({id:g.id,name:g.label,color:colorOf(g),values:g.stats.map(x=>x.retention)})),labels,{format:v=>String(Math.round(v)),referenceValue:100})+'</section>':'';
