 const comparison=a.race.participant.entity==='team'?'<label id="segment-comparison-field">Jämför mot<select id="segment-comparison"><option value="class" '+(state.segmentComparison!=='field'?'selected':'')+'>Egen klass</option><option value="field" '+(state.segmentComparison==='field'?'selected':'')+'>Hela fältet</option></select></label>':'';
 const lab='<section class="card segment-lab"><div class="segment-controls"><label>Från<select id="segment-from">'+fromOptions+'</select></label><label>Till<select id="segment-to">'+toOptions+'</select></label><label>Sortera<select id="segment-metric"><option value="time" '+(state.segmentMetric==='time'?'selected':'')+'>Snabbast tid</option><option value="relative" '+(state.segmentMetric==='relative'?'selected':'')+'>Bäst mot median</option><option value="gain" '+(state.segmentMetric==='gain'?'selected':'')+'>Flest vunna platser</option></select></label>'+comparison+'</div><div class="podium">'+(podium.length?podium.map((item,index)=>'<article class="place-'+(index+1)+'"><b>'+(index+1)+'</b><strong>'+esc(item.r.name)+'</strong><small>'+esc(a.race.participant.entity==='team'?item.r.class_name||'':'#'+item.r.bib)+'</small><span>'+esc(format(item))+'</span></article>').join(''):empty('Kompletta passager saknas för valet.'))+'</div><div class="ranking">'+rest.map((item,index)=>'<button type="button" class="ranking-row" data-result="'+esc(item.r.source_result_id)+'"><b>'+(index+4)+'</b><span><strong>'+esc(item.r.name)+'</strong><small>#'+esc(item.r.bib)+' · '+esc(item.r.class_name||'')+'</small></span><em>'+esc(format(item))+'</em></button>').join('')+'</div></section>';
 const finish='<section class="card"><div class="card-heading"><div><p class="eyebrow">FÄLTETS MÅLGÅNG</p><h3>När hade fältet gått i mål?</h3></div>'+info('field-finish-method','Visar tidpunkten då 10, 25, 50, 75 respektive 90 % av de fullföljande hade gått i mål. Serier separeras på kön eller publicerad lagklass när underlaget räcker.')+'</div><p class="panel-copy">Visar tidpunkten då 10, 25, 50, 75 respektive 90 % av de fullföljande hade gått i mål.</p>'+fieldProgression(a,rows)+'</section>';
 const flow='<section class="card"><div class="card-heading"><div><p class="eyebrow">FÄLTETS FLÖDE</p><h3>Så sprids startfältet</h3></div>'+info('field-spread-method','Topp 10 %-gräns, median och 90 %-gräns bygger på faktiska ackumulerade passagetider vid analyskontroller. Minst 20 observationer krävs för yttergränserna.')+'</div>'+fieldSpread(a,rows,state)+'</section>';
 return lab+'<div class="feature-grid equal-panels">'+finish+flow+'</div>'+standoutPanel(a,rows,state);
